bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
repo=/home/gace/Project/Gserver/projects/TGtumbler/create-videobot
test "$(docker inspect "$cid" --format '{{.State.Running}}' 2>/dev/null)" = true || exit 61
test "$(docker ps --filter label=com.docker.compose.project=gace-createvdobot --filter label=com.docker.compose.service=videobot-poll -q | wc -l)" -eq 1 || exit 62
test -d "$repo/.git" || exit 63
echo "SOURCE_CHECKOUT_HEAD=$(git -C "$repo" rev-parse HEAD)"
echo "LIVE_CONTAINER_IMAGE=$(docker inspect "$cid" --format '{{.Image}}')"
for p in src/telegram/menuPanel.mjs src/telegram/creatorWizard.mjs src/telegram/creatorBot.mjs; do
 echo "LIVE_FILE_HASH $(docker exec "$cid" sha256sum "/opt/videobot/$p" | cut -d' ' -f1) $p"
done
docker exec -i "$cid" node --input-type=module <<'NODE'
import {menuPage} from '/opt/videobot/src/telegram/menuPanel.mjs';
for(const k of ['home','purchase']){
  try{
    const p=menuPage(k);
    console.log('MENU_PAGE',k,JSON.stringify({text:p.text,keyboard:p.reply_markup.inline_keyboard}));
  }catch(e){console.log('MENU_PAGE',k,'UNAVAILABLE',e.message)}
}
NODE
echo "LIVE_SINGLE_POLLER=PASS"
